// Bounded exact sparse row elimination over a supplied prime field.
// Input is generated by verify_s61_macaulay_degree3.py. The result concerns
// that finite-field Macaulay matrix only, not a characteristic-zero fiber.
#include <chrono>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

using Row = std::vector<std::pair<int, int>>;

int power(int a, int n, int prime) {
  int result = 1;
  for (; n; n >>= 1, a = int(int64_t(a) * a % prime))
    if (n & 1) result = int(int64_t(result) * a % prime);
  return result;
}

int main(int argc, char **argv) {
  if (argc != 4) return 2;
  std::ifstream input(argv[1]);
  int prime, row_count, column_count;
  input >> prime >> row_count >> column_count;
  std::vector<int> degree(column_count);
  for (auto &value : degree) input >> value;
  std::vector<Row> basis(column_count), new_lower_rows;
  size_t entries = 0, entry_limit = std::stoull(argv[3]);
  int rank = 0, processed = 0, counts[4] = {0};
  double seconds = std::stod(argv[2]);
  auto start = std::chrono::steady_clock::now();
  std::string status = "complete";
  for (int row_index = 0; row_index < row_count; ++row_index) {
    int size;
    input >> size;
    Row row(size);
    for (auto &entry : row) input >> entry.first >> entry.second;
    if (!input) return 3;
    while (!row.empty()) {
      if (std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count() > seconds) {
        status = "time_limit";
        goto finish;
      }
      if (entries > entry_limit) {
        status = "entry_limit";
        goto finish;
      }
      int pivot = row.front().first;
      if (basis[pivot].empty()) {
        int inverse = power(row.front().second, prime - 2, prime);
        for (auto &entry : row) entry.second = int(int64_t(entry.second) * inverse % prime);
        if (row_index >= 134 && degree[pivot] <= 2) new_lower_rows.push_back(row);
        entries += row.size();
        basis[pivot] = std::move(row);
        ++rank;
        ++counts[degree[pivot]];
        break;
      }
      const Row &old = basis[pivot];
      int scale = row.front().second;
      Row next;
      next.reserve(row.size() + old.size());
      size_t i = 0, j = 0;
      while (i < row.size() || j < old.size()) {
        int key, value;
        if (j == old.size() || (i < row.size() && row[i].first < old[j].first)) {
          key = row[i].first;
          value = row[i++].second;
        } else if (i == row.size() || old[j].first < row[i].first) {
          key = old[j].first;
          value = int((prime - int64_t(scale) * old[j++].second % prime) % prime);
        } else {
          key = row[i].first;
          value = int((row[i++].second - int64_t(scale) * old[j++].second % prime + prime) % prime);
        }
        if (value) next.emplace_back(key, value);
      }
      row.swap(next);
    }
    ++processed;
  }
finish:
  std::cout << "{\"status\":\"" << status << "\",\"prime\":" << prime
            << ",\"rows_total\":" << row_count << ",\"rows_processed\":" << processed
            << ",\"rank\":" << rank << ",\"pivot_counts\":[" << counts[0] << ','
            << counts[1] << ',' << counts[2] << ',' << counts[3]
            << "],\"entries\":" << entries << ",\"elapsed_seconds\":"
            << std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count()
            << ",\"new_lower_degree_rows\":[";
  for (size_t i = 0; i < new_lower_rows.size(); ++i) {
    if (i) std::cout << ',';
    std::cout << '[';
    for (size_t j = 0; j < new_lower_rows[i].size(); ++j) {
      if (j) std::cout << ',';
      std::cout << '[' << new_lower_rows[i][j].first << ',' << new_lower_rows[i][j].second << ']';
    }
    std::cout << ']';
  }
  std::cout << "]}" << std::endl;
}
